from rdkit import Chem
s1='[N][#C][C][Branch2][Ring1][=Branch1][C][=C][C][=C][Branch1][N][O][C][C][C][N][C][C][C][C][Ring1][Branch1][C][=C][Ring1][#C][C][C][C][=Branch1][C][=O][C][C][Ring2][Ring1][=Branch1]'
s2='[N][#C][C][Branch2][Ring1][=Branch1][C][=C][C][=C][Branch1][N][O][C][C][C][N][C][C][C][C][Ring1][Branch1][C][=C][Ring1][#C][C][C][C][Branch1][C][O][C][C][Ring2][Ring1][=Branch1]'
for label,s in [('input',s1),('product',s2)]:
    m=Chem.MolFromSmiles(s)
    print(label, 'parsed=', m is not None, 'atoms=', m.GetNumAtoms() if m else None)
    if m:
        print(Chem.MolToSmiles(m))
        for b in m.GetBonds():
            if b.GetBondType()!=Chem.BondType.SINGLE:
                print(label, b.GetBeginAtomIdx(), b.GetEndAtomIdx(), str(b.GetBondType()))
print('atom counts', len(Chem.MolFromSmiles(s1).GetAtoms()), len(Chem.MolFromSmiles(s2).GetAtoms()))
